CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(40) UNIQUE NOT NULL,pass VARCHAR(255) NOT NULL,fullname VARCHAR(100) NOT NULL,role ENUM('cashier','manager','admin') NOT NULL DEFAULT 'cashier',active TINYINT NOT NULL DEFAULT 1,created_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE settings(k VARCHAR(40) PRIMARY KEY,v VARCHAR(255) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE machines(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(40) UNIQUE NOT NULL,zone VARCHAR(40) DEFAULT 'Thường',rate_hour INT NOT NULL DEFAULT 6000,status ENUM('available','busy','maintenance') NOT NULL DEFAULT 'available') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE members(id INT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(20) UNIQUE NOT NULL,name VARCHAR(100) NOT NULL,phone VARCHAR(20),balance BIGINT NOT NULL DEFAULT 0,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,CONSTRAINT bal_ok CHECK(balance>=0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE wallet_tx(id INT AUTO_INCREMENT PRIMARY KEY,member_id INT NOT NULL,type ENUM('topup','pay','refund') NOT NULL,amount BIGINT NOT NULL,balance_after BIGINT NOT NULL,note VARCHAR(100),user_id INT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(member_id) REFERENCES members(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE sessions(id INT AUTO_INCREMENT PRIMARY KEY,machine_id INT NOT NULL,member_id INT NULL,user_id INT NOT NULL,start_at DATETIME NOT NULL,end_at DATETIME NULL,rate_hour INT NOT NULL,minutes INT NULL,fee INT NULL,status ENUM('open','closed') NOT NULL DEFAULT 'open',invoice_id INT NULL,FOREIGN KEY(machine_id) REFERENCES machines(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE products(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,category VARCHAR(40) DEFAULT 'Đồ uống',price INT NOT NULL,stock INT NOT NULL DEFAULT 0,min_stock INT NOT NULL DEFAULT 5,active TINYINT NOT NULL DEFAULT 1,CONSTRAINT stock_ok CHECK(stock>=0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE suppliers(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,phone VARCHAR(20)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE stock_moves(id INT AUTO_INCREMENT PRIMARY KEY,product_id INT NOT NULL,type ENUM('in','sale','adjust','refund') NOT NULL,qty INT NOT NULL,supplier_id INT NULL,note VARCHAR(150),user_id INT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE orders(id INT AUTO_INCREMENT PRIMARY KEY,member_id INT NULL,user_id INT NOT NULL,total INT NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE order_items(id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,product_id INT NOT NULL,name VARCHAR(100) NOT NULL,price INT NOT NULL,qty INT NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE invoices(id INT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(30) UNIQUE NOT NULL,kind ENUM('session','order') NOT NULL,ref_id INT NOT NULL,member_id INT NULL,user_id INT NOT NULL,total INT NOT NULL,status ENUM('paid','refunded') NOT NULL DEFAULT 'paid',refund_reason VARCHAR(200),shift_id INT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE payments(id INT AUTO_INCREMENT PRIMARY KEY,invoice_id INT NOT NULL UNIQUE,method ENUM('cash','wallet','transfer') NOT NULL,amount INT NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(invoice_id) REFERENCES invoices(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE maintenance(id INT AUTO_INCREMENT PRIMARY KEY,machine_id INT NOT NULL,reporter_id INT NOT NULL,assignee_id INT NULL,issue VARCHAR(250) NOT NULL,status ENUM('open','doing','done') NOT NULL DEFAULT 'open',result VARCHAR(250),created_at DATETIME DEFAULT CURRENT_TIMESTAMP,closed_at DATETIME NULL,FOREIGN KEY(machine_id) REFERENCES machines(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE shifts(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,open_at DATETIME NOT NULL,close_at DATETIME NULL,open_cash INT NOT NULL DEFAULT 0,expected_cash INT NULL,counted_cash INT NULL,status ENUM('open','closed') NOT NULL DEFAULT 'open') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE audit_log(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,action VARCHAR(60) NOT NULL,detail VARCHAR(300),ip VARCHAR(45),created_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
